    "answer": 0,
    "difficulty": "進階",
    "question": "\n<div class=\"reading-article\" style=\"background: var(--bg-secondary); padding: 1.5rem; border-radius: var(--radius-md); margin-bottom: 1.5rem; line-height: 1.6; border-left: 4px solid var(--color-primary);\">\n    <span class=\"en-assist\" data-tw=\"點擊朗讀文章\" data-en=\"Climate change is one of the most pressing issues of our time. It refers to long-term shifts in temperatures and weather patterns. These shifts may be natural, but since the 1800s, human activities have been the main driver of climate change, primarily due to the burning of fossil fuels like coal, oil, and gas. Burning fossil fuels generates greenhouse gas emissions that act like a blanket wrapped around the Earth, trapping the sun's heat and raising temperatures. Examples of greenhouse gas emissions that are causing climate change include carbon dioxide and methane.\" style=\"display: block;\">\n        Climate change is one of the most pressing issues of our time. It refers to long-term shifts in temperatures and weather patterns. These shifts may be natural, but since the 1800s, human activities have been the main driver of climate change, primarily due to the burning of fossil fuels like coal, oil, and gas. Burning fossil fuels generates greenhouse gas emissions that act like a blanket wrapped around the Earth, trapping the sun's heat and raising temperatures. Examples of greenhouse gas emissions that are causing climate change include carbon dioxide and methane. <span class=\"speak-icon\" style=\"cursor: pointer; float: right; font-size: 1.2rem;\" title=\"朗讀文章\">🔊</span>\n    </span>\n</div>\n<div class=\"question-prompt\" style=\"font-weight: 600; margin-bottom: 1rem;\">\n    <span class=\"en-assist\" data-tw=\"選出正確答案\">What is the main topic of this passage?<span class=\"speak-icon\">🔊</span></span>\n</div>",
    "explanation": "\n💡 <strong>題目與選項翻譯：</strong><br>題目：這篇文章的主題是什麼？<br><br>「The overview of the subject」：該主題的概述<br>「The future predictions」：對未來的預測<br>「A specific historical event」：一個特定的歷史事件<br>「Personal opinions of the author」：作者的個人觀點<br><br>💡 <strong>答案解析：</strong><br>\n文章主要在概述該主題的定義與背景。<br><br>\n💡 <strong>文章完整翻譯：</strong><br>\n氣候變遷是我們這個時代最緊迫的問題之一。它指的是溫度和天氣模式的長期轉變。這些轉變可能是自然的，但自1800年代以來，人類活動一直是氣候變遷的主要驅動力，這主要是由於燃燒煤炭、石油和天然氣等化石燃料。燃燒化石燃料會產生溫室氣體排放，這些排放物就像包裹在地球周圍的毯子一樣，困住了太陽的熱量並使溫度升高。導致氣候變遷的溫室氣體排放例子包括二氧化碳和甲烷。",
