    "difficulty": "進階",
    "question": "\n<div class=\"reading-article\" style=\"background: var(--bg-secondary); padding: 1.5rem; border-radius: var(--radius-md); margin-bottom: 1.5rem; line-height: 1.6; border-left: 4px solid var(--color-primary);\">\n    <span class=\"en-assist\" data-tw=\"點擊朗讀文章\" data-en=\"Space exploration is the use of astronomy and space technology to explore outer space. While the exploration of space is carried out mainly by astronomers with telescopes, its physical exploration though is conducted both by unmanned robotic space probes and human spaceflight. Space exploration, like its classical form astronomy, is one of the main sources for space science.\" style=\"display: block;\">\n        Space exploration is the use of astronomy and space technology to explore outer space. While the exploration of space is carried out mainly by astronomers with telescopes, its physical exploration though is conducted both by unmanned robotic space probes and human spaceflight. Space exploration, like its classical form astronomy, is one of the main sources for space science. <span class=\"speak-icon\" style=\"cursor: pointer; float: right; font-size: 1.2rem;\" title=\"朗讀文章\">🔊</span>\n    </span>\n</div>\n<div class=\"question-prompt\" style=\"font-weight: 600; margin-bottom: 1rem;\">\n    <span class=\"en-assist\" data-tw=\"選出正確答案\">Which word best describes the tone of the passage?<span class=\"speak-icon\">🔊</span></span>\n</div>",
    "explanation": "\n💡 <strong>題目與選項翻譯：</strong><br>題目：哪個詞最能描述這篇文章的語氣？<br><br>「Informative」：提供資訊的<br>「Humorous」：幽默的<br>「Angry」：憤怒的<br>「Sarcastic」：諷刺的<br><br>💡 <strong>答案解析：</strong><br>\n這是一篇客觀提供資訊的文章，因此語氣是 Informative (提供資訊的、增廣見聞的)。<br><br>\n💡 <strong>文章完整翻譯：</strong><br>\n太空探索是利用天文學和太空科技來探索外太空。雖然太空探索主要由天文學家使用望遠鏡進行，但其物理探索則由無人機器人太空探測器和載人太空飛行共同進行。太空探索與其經典形式的天文學一樣，是太空科學的主要來源之一。",
