    "answer": 0,
    "difficulty": "基礎",
    "question": "\n<div class=\"reading-article\" style=\"background: var(--bg-secondary); padding: 1.5rem; border-radius: var(--radius-md); margin-bottom: 1.5rem; line-height: 1.6; border-left: 4px solid var(--color-primary);\">\n    <span class=\"en-assist\" data-tw=\"點擊朗讀文章\" data-en=\"The history of the Internet has its origin in the efforts to build and interconnect computer networks that arose from research and development in the United States and involved international collaboration, particularly with researchers in the United Kingdom and France. The Internet's foundation was laid by ARPANET, funded by the US Department of Defense.\" style=\"display: block;\">\n        The history of the Internet has its origin in the efforts to build and interconnect computer networks that arose from research and development in the United States and involved international collaboration, particularly with researchers in the United Kingdom and France. The Internet's foundation was laid by ARPANET, funded by the US Department of Defense. <span class=\"speak-icon\" style=\"cursor: pointer; float: right; font-size: 1.2rem;\" title=\"朗讀文章\">🔊</span>\n    </span>\n</div>\n<div class=\"question-prompt\" style=\"font-weight: 600; margin-bottom: 1rem;\">\n    <span class=\"en-assist\" data-tw=\"選出正確答案\">What is the main topic of this passage?<span class=\"speak-icon\">🔊</span></span>\n</div>",
    "explanation": "\n💡 <strong>題目與選項翻譯：</strong><br>題目：這篇文章的主題是什麼？<br><br>「The overview of the subject」：該主題的概述<br>「The future predictions」：對未來的預測<br>「A specific historical event」：一個特定的歷史事件<br>「Personal opinions of the author」：作者的個人觀點<br><br>💡 <strong>答案解析：</strong><br>\n文章主要在概述該主題的定義與背景。<br><br>\n💡 <strong>文章完整翻譯：</strong><br>\n網際網路的歷史起源於建立和互連電腦網路的努力，這些努力源於美國的研究與開發，並涉及國際合作，特別是與英國和法國的研究人員。網際網路的基礎是由美國國防部資助的 ARPANET 奠定的。",
