    "answer": 0,
    "difficulty": "中等",
    "question": "\n<div class=\"reading-article\" style=\"background: var(--bg-secondary); padding: 1.5rem; border-radius: var(--radius-md); margin-bottom: 1.5rem; line-height: 1.6; border-left: 4px solid var(--color-primary);\">\n    <span class=\"en-assist\" data-tw=\"點擊朗讀文章\" data-en=\"Artificial Intelligence (AI) is intelligence demonstrated by machines, as opposed to the natural intelligence displayed by animals including humans. AI research has been defined as the field of study of intelligent agents, which refers to any system that perceives its environment and takes actions that maximize its chance of achieving its goals. The term 'artificial intelligence' had previously been used to describe machines that mimic and display human cognitive skills that are associated with the human mind, such as learning and problem-solving.\" style=\"display: block;\">\n        Artificial Intelligence (AI) is intelligence demonstrated by machines, as opposed to the natural intelligence displayed by animals including humans. AI research has been defined as the field of study of intelligent agents, which refers to any system that perceives its environment and takes actions that maximize its chance of achieving its goals. The term 'artificial intelligence' had previously been used to describe machines that mimic and display human cognitive skills that are associated with the human mind, such as learning and problem-solving. <span class=\"speak-icon\" style=\"cursor: pointer; float: right; font-size: 1.2rem;\" title=\"朗讀文章\">🔊</span>\n    </span>\n</div>\n<div class=\"question-prompt\" style=\"font-weight: 600; margin-bottom: 1rem;\">\n    <span class=\"en-assist\" data-tw=\"選出正確答案\">Which word best describes the tone of the passage?<span class=\"speak-icon\">🔊</span></span>\n</div>",
    "explanation": "\n💡 <strong>題目與選項翻譯：</strong><br>題目：哪個詞最能描述這篇文章的語氣？<br><br>「Informative」：提供資訊的<br>「Humorous」：幽默的<br>「Angry」：憤怒的<br>「Sarcastic」：諷刺的<br><br>💡 <strong>答案解析：</strong><br>\n這是一篇客觀提供資訊的文章，因此語氣是 Informative (提供資訊的、增廣見聞的)。<br><br>\n💡 <strong>文章完整翻譯：</strong><br>\n人工智慧（AI）是由機器展示的智慧，相對於包括人類在內的動物所展示的自然智慧。AI 研究被定義為對智慧代理的研究領域，這指的是任何感知其環境並採取行動以最大化實現其目標機會的系統。以前，「人工智慧」一詞曾被用來描述模仿並展示與人類思維相關的人類認知技能（如學習和解決問題）的機器。",
    "id": "e37"
